package dev.buildit.engine.project

import kotlinx.serialization.builtins.MapSerializer
import kotlinx.serialization.builtins.serializer
import java.io.File
import java.security.MessageDigest

/**
 * Tracks files that Build It generates (manifest, Gradle files, code from blocks, layout XML).
 *
 * Each generated file's SHA-256 is recorded in `.buildit/generated.json`. Before regenerating, the
 * current content is compared with the recorded hash: if the user edited the file since Build It
 * last wrote it, the write is refused with [WriteResult.UserModified] instead of silently
 * overwriting their work. The caller then asks the user (overwrite, keep, or compare).
 */
class GeneratedFiles(private val projectDir: File) {
    sealed interface WriteResult {
        data object Written : WriteResult
        data object Unchanged : WriteResult
        /** The file on disk differs from what Build It last generated. Nothing was written. */
        data class UserModified(val path: String) : WriteResult
    }

    private val registryFile = File(projectDir, "${ProjectFormat.INTERNAL_DIR}/generated.json")
    private val serializer = MapSerializer(String.serializer(), String.serializer())

    private fun registry(): MutableMap<String, String> =
        if (registryFile.isFile) runCatching { ProjectJson.decodeFromString(serializer, registryFile.readText()).toMutableMap() }.getOrElse { mutableMapOf() }
        else mutableMapOf()

    private fun saveRegistry(map: Map<String, String>) =
        AtomicFiles.writeText(registryFile, ProjectJson.encodeToString(serializer, map.toSortedMap()))

    /** True when [path] exists and differs from what Build It last generated. */
    fun isUserModified(path: String): Boolean {
        val file = resolve(path)
        if (!file.isFile) return false
        val recorded = registry()[path] ?: return true // exists but never generated by us
        return sha256(file.readBytes()) != recorded
    }

    fun write(path: String, content: String, force: Boolean = false): WriteResult {
        val file = resolve(path)
        val bytes = content.toByteArray(Charsets.UTF_8)
        val newHash = sha256(bytes)
        val reg = registry()
        if (file.isFile) {
            val currentHash = sha256(file.readBytes())
            if (currentHash == newHash) {
                if (reg[path] != newHash) { reg[path] = newHash; saveRegistry(reg) }
                return WriteResult.Unchanged
            }
            if (!force && reg[path] != currentHash) return WriteResult.UserModified(path)
        }
        AtomicFiles.writeBytes(file, bytes)
        reg[path] = newHash
        saveRegistry(reg)
        return WriteResult.Written
    }

    /** True when Build It generates [path] (e.g. from blocks or project settings). */
    fun isTracked(path: String): Boolean = registry().containsKey(path)

    /** Stops tracking [path], e.g. when the user takes ownership of a generated file. */
    fun release(path: String) {
        val reg = registry()
        if (reg.remove(path) != null) saveRegistry(reg)
    }

    private fun resolve(path: String): File {
        val f = File(projectDir, path).canonicalFile
        require(f.path.startsWith(projectDir.canonicalPath + File.separator)) { "Path escapes project: $path" }
        return f
    }

    companion object {
        fun sha256(bytes: ByteArray): String =
            MessageDigest.getInstance("SHA-256").digest(bytes).joinToString("") { "%02x".format(it) }
    }
}

